import org.junit.Test;
import static org.junit.Assert.*;
import org.mockito.Mockito;

public class KeyPairTest {

    @Test
    public void newKeyPairFromPublicKeypairTest() {
        EdDSAPublicKey publicKey = Mockito.mock(EdDSAPublicKey.class);
        KeyPair keyPair = new KeyPair(publicKey);
        assertNotNull(keyPair);
    }

    @Test
    public void canSignTest() {
        KeyPair keyPair = Mockito.mock(KeyPair.class);
        when(keyPair.canSign()).thenReturn(true);
        assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeedByteTest() {
        byte[] seed = "1234567890".getBytes();
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);
        assertNotNull(keyPair);
    }

    @Test
    public void fromSecretSeedStringTest() {
        String seed = "1234567890";
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);
        assertNotNull(keyPair);
    }

    @Test
    public void fromAccountIdTest() {
        String accountId = "XED4B6G2F8A2JG3L9C7P1H5T6V3D4";
        KeyPair keyPair = KeyPair.fromAccountId(accountId);
        assertNotNull(keyPair);
    }

    @Test
    public void fromPublicKeyTest() {
        byte[] publicKey = "1234567890".getBytes();
        KeyPair keyPair = KeyPair.fromPublicKey(publicKey);
        assertNotNull(keyPair);
    }

    @Test
    public void fromBip39SeedTest() {
        byte[] bip39Seed = "1234567890".getBytes();
        int accountNumber = 1;
        KeyPair keyPair = KeyPair.fromBip39Seed(bip39Seed, accountNumber);
        assertNotNull(keyPair);
    }

    @Test
    public void randomTest() {
        KeyPair keyPair = KeyPair.random();
        assertNotNull(keyPair);
    }

    @Test
    public void getAccountIdTest() {
        KeyPair keyPair = Mockito.mock(KeyPair.class);
        when(keyPair.getAccountId()).thenReturn("XED4B6G2F8A2JG3L9C7P1H5T6V3D4");
        assertEquals("XED4B6G2F8A2JG3L9C7P1H5T6V3D4", keyPair.getAccountId());
    }

    @Test
    public void getSecretSeedTest() {
        KeyPair keyPair = Mockito.mock(KeyPair.class);
        when(keyPair.getSecretSeed()).thenReturn("1234567890".getBytes());
        assertArrayEquals("1234567890".getBytes(), keyPair.getSecretSeed());
    }

    @Test
    public void getPublicKeyTest() {
        KeyPair keyPair = Mockito.mock(KeyPair.class);
        when(keyPair.getPublicKey()).thenReturn("1234567890".getBytes());
        assertArrayEquals("1234567890".getBytes(), keyPair.getPublicKey());
    }

    @Test
    public void signTest() throws GeneralSecurityException, IOException {
        byte[] data = "Hello World!".getBytes();
        KeyPair keyPair = Mockito.mock(KeyPair.class);
        when(keyPair.sign(data)).thenReturn("signature".getBytes());
        assertArrayEquals("signature".getBytes(), keyPair.sign(data));
    }

    @Test
    public void verifyTest() throws GeneralSecurityException, IOException {
        byte[] data = "Hello World!".getBytes();
        byte[] signature = "signature".getBytes();
        KeyPair keyPair = Mockito.mock(KeyPair.class);
        when(keyPair.verify(data, signature)).thenReturn(true);
        assertTrue(keyPair.verify(data, signature));
    }

    @Test
    public void equalsTest() {
        KeyPair keyPair1 = Mockito.mock(KeyPair.class);
        KeyPair keyPair2 = Mockito.mock(KeyPair.class);
        when(keyPair1.equals(anyObject())).thenReturn(true);
        when(keyPair2.equals(anyObject())).thenReturn(false);
        assertTrue(keyPair1.equals(keyPair2));
    }

